import { useEffect, useState } from "react";
import { io } from "socket.io-client";
import "./PatientDashboard.css";

const socket = io("http://localhost:5000");

function PatientDashboard() {

  const [myOP, setMyOP] = useState(null);

  const [form, setForm] = useState({
    patientName: "",
    department: "",
    date: ""
  });

  const [queueCount, setQueueCount] = useState(0);

  useEffect(() => {

    const fetchData = async () => {

      const res = await fetch(
        "http://localhost:5000/api/queue/all"
      );

      const data = await res.json();

      const mine = data.find(
        q => q.patientName === form.patientName
      );

      if (mine) {
        setMyOP(mine);
      }

      const total = data.filter(
        q => q.status === "InQueue"
      ).length;

      setQueueCount(total);

    };

    fetchData();

    socket.on(
      "queueUpdated",
      fetchData
    );

    return () => {
      socket.off("queueUpdated");
    };

  }, [form.patientName]);



  const bookOP = async () => {

    const res = await fetch(
      "http://localhost:5000/api/queue/book",
      {
        method: "POST",

        headers: {
          "Content-Type":
            "application/json"
        },

        body: JSON.stringify(form)
      }
    );

    const data = await res.json();

    setMyOP(data);

  };


  const joinQueue = async (id) => {

    await fetch(
      `http://localhost:5000/api/queue/join/${id}`,
      {
        method: "PUT"
      }
    );

  };


  return (

    <div className="patient-container">

      <div className="patient-card">

        <h1>
          🏥 Smart Queue
        </h1>

        {!myOP && (

          <>

            <input
              placeholder="Patient Name"

              onChange={(e) =>
                setForm({
                  ...form,
                  patientName:
                    e.target.value
                })
              }
            />

            <input
              placeholder="Department"

              onChange={(e) =>
                setForm({
                  ...form,
                  department:
                    e.target.value
                })
              }
            />

            <input
              type="date"

              onChange={(e) =>
                setForm({
                  ...form,
                  date:
                    e.target.value
                })
              }
            />

            <button
              onClick={bookOP}
            >
              Book OP
            </button>

          </>

        )}

        {myOP && (

          <div className="op-card">

            <h2>
              My OP
            </h2>

            <p>

              Token No

              <span>
                {myOP.tokenNumber}
              </span>

            </p>

            <p>

              Department

              <span>
                {myOP.department}
              </span>

            </p>

            <p>

              Status

              <span className="status">

                {myOP.status}

              </span>

            </p>


            {myOP.status ===
              "Confirmed" && (

                <button
                  className="join-btn"

                  onClick={() =>
                    joinQueue(
                      myOP._id
                    )
                  }
                >

                  Join Queue

                </button>

              )}


            {myOP.status ===
              "InQueue" && (

                <div className="queue-box">

                  Queue Waiting

                  <h3>

                    {queueCount}

                  </h3>

                </div>

              )}

          </div>

        )}

      </div>

    </div>

  );

}

export default PatientDashboard;
